#!/usr/bin/env bun
// @bun
function maybeExitWithHelp(arg,help){if(arg==="-h"||arg==="--help"){console.log(help);process.exit(0)}}function runMain(main){main().catch((err)=>{console.error(err instanceof Error?err.message:String(err));process.exit(1)})}var ZONES=["front","middle","back","surprise"];var HELP=`classic-cinema pick-seats \u2014 best adjacent seats in a zone

Usage:
  bun run src/pick-seats.ts --seatmap-file PATH --zone ZONE --count N

Options:
  --seatmap-file PATH   Path to a seating map JSON file (required)
  --zone ZONE           front | middle | back | surprise (required)
  --count N             Number of adjacent seats (required)
  -h, --help            Show this help

Output: comma-joined seat codes on stdout. Expansion note on stderr.
Exit: 0 found, 1 none/invalid map, 64 invalid usage.`;async function loadSeatmap(path){const file=Bun.file(path);const parsed=JSON.parse(await file.text());return Array.isArray(parsed)?parsed:parsed.rows??[]}function getValidRows(rows){return rows.filter((row)=>{const seats=row.seats??[];const hasReal=seats.some((s)=>{const t=s.typeId??"";return t!=="gap"&&t!==""});return hasReal&&(row.name??"").trim().length>0})}function splitZones(rows){const n=rows.length;if(n===0)return{front:[],middle:[],back:[]};const third=Math.max(1,Math.floor(n/3));const front=rows.slice(0,third);const back=rows.slice(n-third);let middle=n>2?rows.slice(third,n-third):rows;if(middle.length===0)middle=rows;return{front,middle,back}}function availableSeats(row){const result=[];const seats=row.seats??[];seats.forEach((seat,i)=>{const typeId=seat.typeId??"standard";if(typeId==="gap"||typeId==="wheelchair"||typeId==="companion")return;if(seat.sold||seat.unavailable)return;result.push([i,seat.name??`${row.name}${i+1}`])});return result}function findAdjacentRuns(seats,count){if(seats.length<count)return[];const runs=[];for(let start=0;start<=seats.length-count;start++){const run=seats.slice(start,start+count);const consecutive=run.every((s,j)=>j===0||s[0]-run[j-1][0]===1);if(consecutive)runs.push(run)}return runs}function scoreRun(run,rowTotalSeats){const center=(rowTotalSeats-1)/2;const avgIdx=run.reduce((sum,s)=>sum+s[0],0)/run.length;return Math.abs(avgIdx-center)}var ZONE_EXPANSION={front:["front","middle","back"],middle:["middle","front","back"],back:["back","middle","front"],surprise:["middle","front","back"]};function findBestRun(zoneRows,count){if(zoneRows.length===0)return null;const zoneCenter=(zoneRows.length-1)/2;const sortedRows=zoneRows.map((row,idx)=>({row,idx})).sort((a,b)=>Math.abs(a.idx-zoneCenter)-Math.abs(b.idx-zoneCenter));let bestRun=null;let bestScore=Number.POSITIVE_INFINITY;for(const{row}of sortedRows){const seats=availableSeats(row);const totalSeats=(row.seats??[]).length;for(const run of findAdjacentRuns(seats,count)){const score=scoreRun(run,totalSeats);if(score<bestScore){bestScore=score;bestRun=run}}}return bestRun}function pickSeats(rows,zoneName,count){const validRows=getValidRows(rows);const{front,middle,back}=splitZones(validRows);const zoneMap={front,middle,back,surprise:middle};for(const tryZone of ZONE_EXPANSION[zoneName]??["middle","front","back"]){const zoneRows=zoneMap[tryZone]??middle;const bestRun=findBestRun(zoneRows,count);if(bestRun){return{codes:bestRun.map((s)=>s[1]),zoneUsed:tryZone}}}return null}function exitWithUsageError(message){console.error(message);console.error(HELP);process.exit(64)}function exitWithUnknownArg(arg){console.error(`Unknown argument: ${arg}`);console.error(HELP);process.exit(64)}function readFlagArg(argv,index,flag){if(argv[index]===`--${flag}`)return{value:argv[index+1]??"",consumed:2};const prefix=`--${flag}=`;if(argv[index].startsWith(prefix))return{value:argv[index].slice(prefix.length),consumed:1};return null}function validatePickSeatsArgs(raw){const{seatmapFile,zone,count}=raw;if(seatmapFile===null||zone===null||count===null||Number.isNaN(count)){exitWithUsageError("Missing/invalid required --seatmap-file, --zone, --count")}if(!ZONES.includes(zone)){exitWithUsageError(`Invalid --zone '${zone}' (choose: ${ZONES.join(", ")})`)}return{seatmapFile,zone,count}}function parseArgs(argv){const raw={seatmapFile:null,zone:null,count:null};let i=0;while(i<argv.length){const arg=argv[i];maybeExitWithHelp(arg,HELP);const seatmapFlag=readFlagArg(argv,i,"seatmap-file");if(seatmapFlag){raw.seatmapFile=seatmapFlag.value;i+=seatmapFlag.consumed;continue}const zoneFlag=readFlagArg(argv,i,"zone");if(zoneFlag){raw.zone=zoneFlag.value;i+=zoneFlag.consumed;continue}const countFlag=readFlagArg(argv,i,"count");if(countFlag){raw.count=Number.parseInt(countFlag.value,10);i+=countFlag.consumed;continue}exitWithUnknownArg(arg)}return validatePickSeatsArgs(raw)}async function main(){const{seatmapFile,zone,count}=parseArgs(process.argv.slice(2));let rows;try{rows=await loadSeatmap(seatmapFile)}catch(err){const msg=err instanceof Error?err.message:String(err);console.error(`Error: cannot read seating map: ${msg}`);process.exit(1)}if(rows.length===0){console.error("Error: empty or invalid seating map");process.exit(1)}const result=pickSeats(rows,zone,count);if(!result){console.error(`Error: no ${count} adjacent seats found in any zone`);process.exit(1)}console.log(result.codes.join(", "));if(result.zoneUsed!==zone&&zone!=="surprise"){console.error(`Note: expanded from ${zone} to ${result.zoneUsed}`)}}if(import.meta.main){runMain(main)}export{pickSeats};
